/*
 * Xiclos TV - ARRANQUE
 *
 * Este archivo conserva el nombre jquery.min.js porque es el primero que
 * cargan los index.html empaquetados de LG, Samsung y Amazon (que no se
 * pueden modificar sin volver a homologar). Hace dos cosas:
 *
 *  1. Decide, según la plataforma, si corre la v2 o la versión anterior
 *     (copias en common/legacy/ y amazon/legacy/).
 *  2. Carga una sola versión de jQuery (1.12.4 para la v2).
 *
 * Para pasar Amazon a la v2 más adelante: AMAZON_V2 = true.
 *
 * ES5 puro.
 */
(function () {
  "use strict";

  // Amazon pasa a la v2 (la versión anterior queda como respaldo: ver ?v1=1)
  var AMAZON_V2 = true;
  var JQUERY_URL = "https://code.jquery.com/jquery-1.12.4.min.js";

  function detectPlatform() {
    // Para páginas de prueba: window.XTV_FORCE_PLATFORM = "amazon" | "webos" | "tizen" | "desktop"
    if (window.XTV_FORCE_PLATFORM) {
      return window.XTV_FORCE_PLATFORM;
    }
    var ua = navigator.userAgent || "";
    if (/AmazonWebAppPlatform|\bAFT[A-Z0-9]*\b|Silk\//.test(ua)) {
      return "amazon";
    }
    if (/web0s|webos/i.test(ua)) {
      return "webos";
    }
    if (/tizen/i.test(ua)) {
      return "tizen";
    }
    return "desktop";
  }

  // URL de este archivo, para ubicar el resto sin importar desde dónde se sirve
  function currentSrc() {
    if (document.currentScript && document.currentScript.src) {
      return document.currentScript.src;
    }
    var scripts = document.getElementsByTagName("script");
    for (var i = scripts.length - 1; i >= 0; i--) {
      if (/\/common\/js\/jquery\.min\.js/.test(scripts[i].src || "")) {
        return scripts[i].src;
      }
    }
    return "";
  }

  var src = currentSrc();
  var cut = src.indexOf("common/js/jquery.min.js");
  var root = cut >= 0 ? src.substring(0, cut) : "../";
  var platform = detectPlatform();
  // ?v1=1 en la dirección fuerza la versión anterior en Amazon (comparar o
  // emergencia); ?v2=1, la v2. Solo afecta a quien abre la app así.
  var search = (window.location && window.location.search) || "";
  var amazonV2 = /[?&]v1=1/.test(search) ? false : /[?&]v2=1/.test(search) ? true : AMAZON_V2;
  var legacy = platform === "amazon" && !amazonV2;

  var boot = {
    platform: platform,
    legacy: legacy,
    root: root,
    // Carga sincrónica de una copia de la versión anterior, en el mismo
    // lugar del orden de carga que el archivo que la llama.
    load: function (name) {
      document.write('<script src="' + root + "common/legacy/js/" + name + '"><\/script>');
    },
    loadAmazon: function (name) {
      document.write('<script src="' + root + "amazon/legacy/js/" + name + '"><\/script>');
    }
  };
  window.XTV_BOOT = boot;

  if (legacy) {
    // Versión anterior: su propio jQuery (1.8.3) y, al terminar de cargar,
    // sus hojas de estilo (como hacía el selector de versión anterior).
    boot.load("jquery.min.js");
    document.addEventListener("DOMContentLoaded", function () {
      var files = ["site.css", "slider.css"];
      for (var i = 0; i < files.length; i++) {
        var link = document.createElement("link");
        link.rel = "stylesheet";
        link.href = root + "common/legacy/css/" + files[i];
        document.getElementsByTagName("head")[0].appendChild(link);
      }
    });
  } else {
    // v2: jQuery 1.12.4. Si el CDN no responde, se usa la copia local.
    document.write('<script src="' + JQUERY_URL + '"><\/script>');
    document.write(
      "<script>window.jQuery||document.write('<script src=\"" +
        root +
        "common/legacy/js/jquery.min.js\"><\\/script>')<\/script>"
    );
  }
})();
